// Bottom-up merge sort, in place in main: O(n log n) and no array parameters.
fn main() -> Void {
    let n: Int = 5000;
    let xs: Int[] = [];
    setlength(xs, n);
    let x: Int = 42;
    loop k in 0..n {
        x = (1103515245 * x + 12345) % 2147483648;
        xs[k] = x % 100000;
    }
    let tmp: Int[] = [];
    setlength(tmp, n);
    let width: Int = 1;
    loop width < n {
        let lo: Int = 0;
        loop lo < n {
            let mid: Int = min(lo + width, n);
            let hi: Int = min(lo + 2 * width, n);
            let i: Int = lo;
            let j: Int = mid;
            let k: Int = lo;
            loop k < hi {
                if i < mid && (j >= hi || xs[i] <= xs[j]) {
                    tmp[k] = xs[i];
                    i = i + 1;
                } else {
                    tmp[k] = xs[j];
                    j = j + 1;
                }
                k = k + 1;
            }
            lo = lo + 2 * width;
        }
        loop t in 0..n {
            xs[t] = tmp[t];
        }
        width = width * 2;
    }
    let checksum: Int = 0;
    loop k in 0..n {
        checksum = (checksum + k * xs[k]) % 1000000007;
    }
    fx {
        println("first = ", xs[0], " ", xs[1], " ", xs[2], " ", xs[3], " ", xs[4]);
        println("last = ", xs[n - 5], " ", xs[n - 4], " ", xs[n - 3], " ", xs[n - 2], " ", xs[n - 1]);
        println("median = ", (xs[2499] + xs[2500]) div 2);
        println("checksum = ", checksum);
    }
    ret;
}

