fn sorted(xs: Int[]) -> Int[] {
    let out: Int[] = xs;
    loop i in 1..length(out) {
        let v: Int = out[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if out[j] <= v {
                break;
            }
            out[j + 1] = out[j];
            j = j - 1;
        }
        out[j + 1] = v;
    }
    ret out;
}

fn main() -> Void {
    let xs: Int[] = [];
    let x: Int = 42;
    loop k in 0..5000 {
        x = (1103515245 * x + 12345) % 2147483648;
        xs = xs + [x % 100000];
    }
    let s: Int[] = sorted(xs);
    let n: Int = length(s);
    let checksum: Int = 0;
    loop k in 0..n {
        checksum = (checksum + k * s[k]) % 1000000007;
    }
    let median: Int = (s[2499] + s[2500]) / 2;
