    let n: Int = 100000;
    let a: Int[] = [];
    setlength(a, n);
    loop i in 0..n {
        a[i] = 3 * i + 1;
    }
    let found: Int = 0;
    let indexSum: Int = 0;
    // The search runs inline: a helper taking `a` would copy all of it per call.
    loop j in 0..10000 {
        let q: Int = (j * 7919) % 300007;
        let lo: Int = 0;
        let hi: Int = n - 1;
        let at: Int = -1;
        loop lo <= hi && at < 0 {
            let mid: Int = (lo + hi) div 2;
            if a[mid] == q {
                at = mid;
            } else if a[mid] < q {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        if at >= 0 {
            found = found + 1;
            indexSum = indexSum + at;
        }
    }
    fx {
        println("found = ", found);
        println("index sum = ", indexSum);
    }
    ret;
}

