fn bsearch(xs: Int[], target: Int) -> Int {
    let lo: Int = 0;
    let hi: Int = length(xs) - 1;
    loop lo <= hi {
        let mid: Int = (lo + hi) div 2;
        if xs[mid] == target {
            ret mid;
        }
        if xs[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    ret -1;
}

fn main() -> Void {
