type Memo {
    vals: Int[] = [];
}

// The memo lives in a record: records are pointer-backed, so every call sees
// the same table (an Int[] parameter would be a fresh copy per call).
fn fib(n: Int, m: Memo) -> Int {
    if m.vals[n] >= 0 {
        ret m.vals[n];
    }
    let v: Int = fib(n - 1, m) + fib(n - 2, m);
    m.vals[n] = v;
    ret v;
}

fn main() -> Void {
    let m: Memo = new Memo();
    setlength(m.vals, 91);
    loop i in 0..91 {
        m.vals[i] = -1;
    }
    m.vals[0] = 0;
    m.vals[1] = 1;
    let total: Int = 0;
    loop i in 0..91 {
        total = total + fib(i, m);
    }
    fx {
        println("fib(30) = ", fib(30, m));
        println("fib(60) = ", fib(60, m));
        println("fib(90) = ", fib(90, m));
        println("sum = ", total);
    }
    ret;
}

