// Iterative DFS with an explicit stack in main: no array crosses a call.
fn main() -> Void {
    let n: Int = 1000;
    let visited: Bool[] = [];
    setlength(visited, n);
    let order: Int[] = [];
    // A preallocated stack with a top index: slicing to pop would copy it.
    let stack: Int[] = [];
    setlength(stack, 3 * n + 1);
    let top: Int = 1;
    loop top > 0 {
        top = top - 1;
        let u: Int = stack[top];
        if !visited[u] {
            visited[u] = true;
            order = order + [u];
            // Push in reverse so the first edge is explored first.
            stack[top] = (u + 1) % n;
            stack[top + 1] = (u * 13 + 11) % n;
            stack[top + 2] = (u * 7 + 3) % n;
            top = top + 3;
        }
    }
    let checksum: Int = 0;
    loop p in 0..length(order) {
        checksum = (checksum + p * order[p]) % 1000000007;
    }
    let first: Text = "";
    loop p in 0..8 {
        if p > 0 {
            first = first + " ";
        }
        first = first + int_to_text(order[p]);
    }
    fx {
        println("reachable = ", length(order));
        println("first = ", first);
        println("checksum = ", checksum);
    }
    ret;
}

