type Walk {
    order: Int[] = [];
}

fn dfs(u: Int, adj: Int[][], visited: Bool[], walk: Walk) -> Bool[] {
    visited[u] = true;
    walk.order = walk.order + [u];
    loop k in 0..length(adj[u]) {
        let v: Int = adj[u][k];
        if !visited[v] {
            visited = dfs(v, adj, visited, walk);
        }
    }
    ret visited;
}

fn main() -> Void {
    let adj: Int[][] = [];
    loop u in 0..1000 {
        let row: Int[] = [(u * 7 + 3) % 1000, (u * 13 + 11) % 1000, (u + 1) % 1000];
        adj = adj + [row];
    }
    let visited: Bool[] = [];
    loop u in 0..1000 {
        visited = visited + [false];
    }
    let walk: Walk = new Walk();
    visited = dfs(0, adj, visited, walk);
    let checksum: Int = 0;
    loop p in 0..length(walk.order) {
        checksum = (checksum + p * walk.order[p]) % 1000000007;
