// The scan runs line by line as the file is read: indexing a short Text is
// cheap, while s[i] on the joined 100 KB Text is O(i). A newline ends a word,
// so per-line counting gives the same answers as one scan of the whole text.
fn main() -> Void {
    let f: File;
    let letters: Int = 0;
    let vowels: Int = 0;
    let words: Int = 0;
    let longest: Int = 0;
    fx {
        assign(f, "corpus.txt");
        reset(f);
        loop {
            if eof(f) {
                break;
            }
            let line: Text;
            readln(f, line);
            let run: Int = 0;
            let n: Int = string_len(line);
            loop i in 0..n + 1 {
                let isLetter: Bool = false;
                if i < n {
                    let c: Int = ord(line[i]);
                    isLetter = c >= 97 && c <= 122;
                    if isLetter {
                        letters = letters + 1;
                        if c == 97 || c == 101 || c == 105 || c == 111 || c == 117 {
                            vowels = vowels + 1;
                        }
                    }
                }
                if isLetter {
                    run = run + 1;
                } else {
                    if run > 0 {
                        words = words + 1;
                        longest = max(longest, run);
                    }
                    run = 0;
                }
            }
        }
        close(f);
        println("letters = ", letters);
        println("vowels = ", vowels);
        println("words = ", words);
        println("longest = ", longest);
    }
    ret;
}

