// Open addressing over 4096 slots with a polynomial hash of the word: one
// probe chain per word instead of a scan of every distinct word so far.
@pure
fn hashWord(w: Text, size: Int) -> Int {
    let h: Int = 0;
    loop i in 0..string_len(w) {
        h = (h * 31 + ord(w[i])) % 1000003;
    }
    ret h % size;
}

fn main() -> Void {
    let size: Int = 4096;
    let keys: Text[] = [];
    let counts: Int[] = [];
    setlength(keys, size);
    setlength(counts, size);
    let total: Int = 0;
    let distinct: Int = 0;
    let f: File;
    fx {
        assign(f, "words.txt");
        reset(f);
        loop {
            if eof(f) {
                break;
            }
            let line: Text;
            readln(f, line);
            if string_len(line) == 0 {
                continue;
            }
            let parts: Text[] = split(line, " ");
            loop w in parts {
                total = total + 1;
                let slot: Int = hashWord(w, size);
                loop counts[slot] > 0 && keys[slot] != w {
                    slot = (slot + 1) % size;
                }
                if counts[slot] == 0 {
                    keys[slot] = w;
                    distinct = distinct + 1;
                }
                counts[slot] = counts[slot] + 1;
            }
        }
        close(f);
    }
    // Ten selection passes: the best (count desc, word asc) not yet taken.
    let taken: Bool[] = [];
    setlength(taken, size);
    fx {
        println("words = ", total);
        println("distinct = ", distinct);
        loop rank in 1..11 {
            let best: Int = -1;
            loop s in 0..size {
                if counts[s] > 0 && !taken[s] {
                    if best < 0 || counts[s] > counts[best] || (counts[s] == counts[best] && keys[s] < keys[best]) {
                        best = s;
                    }
                }
            }
            taken[best] = true;
            println(rank, ". ", keys[best], " ", counts[best]);
        }
    }
    ret;
}

