fn regionIndex(r: Text) -> Int {
    if r == "central" {
        ret 0;
    }
    if r == "east" {
        ret 1;
    }
    if r == "north" {
        ret 2;
    }
    if r == "south" {
        ret 3;
    }
    if r == "west" {
        ret 4;
    }
    ret -1;
}

fn dollars(cents: Int) -> Text {
    let frac: Int = cents % 100;
    let pad: Text = "";
    if frac < 10 {
        pad = "0";
    }
    ret int_to_text(cents div 100) + "." + pad + int_to_text(frac);
}

// The plain getters: every order carries every field, and the `_or` forms
// cost about three times as much per call on the pinned engines.
fn main() -> Void {
    let names: Text[] = ["central", "east", "north", "south", "west"];
    let counts: Int[] = [0, 0, 0, 0, 0];
    let qtys: Int[] = [0, 0, 0, 0, 0];
    let revenue: Int[] = [0, 0, 0, 0, 0];
    let total: Int = 0;
    let bestId: Int = -1;
    let bestValue: Int = -1;
    fx {
        let doc: ToonDoc = toon_parse_file("orders.json");
        let root: ToonNode = toon_root(doc);
        let orders: ToonNode = toon_key(root, "orders");
        let n: Int = toon_len(orders);
        loop i in 0..n {
            let o: ToonNode = toon_at(orders, i);
            let r: Int = regionIndex(toon_get_text(o, "region"));
            let qty: Int = toon_get_int(o, "qty");
            let value: Int = qty * toon_get_int(o, "cents");
            let id: Int = toon_get_int(o, "id");
            if r >= 0 {
                counts[r] = counts[r] + 1;
                qtys[r] = qtys[r] + qty;
                revenue[r] = revenue[r] + value;
            }
            total = total + 1;
            if value > bestValue || (value == bestValue && id < bestId) {
                bestValue = value;
                bestId = id;
            }
        }
        loop k in 0..5 {
            println(names[k], ": orders=", counts[k], " qty=", qtys[k], " revenue=", dollars(revenue[k]));
        }
        println("orders = ", total);
        println("largest = ", bestId);
        toon_close(doc);
    }
    ret;
}

