type RegionTotals {
    name: Text = "";
    orders: Int = 0;
    qty: Int = 0;
    cents: Int = 0;

    fn add(q: Int, c: Int) -> Void {
        self.orders = self.orders + 1;
        self.qty = self.qty + q;
        self.cents = self.cents + q * c;
        ret;
    }
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }
